// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.eclipse.rdf4j.sail.lmdb.evaluation.codegen.KernelRuntime;
import org.junit.jupiter.api.Test;

/** Direct tests of the per-site OPTIONAL replay cache, without a kernel around it. */
class KernelOptionalReplayTest {

	private static final int KEY = 0;
	private static final int VALUE = 1;
	private static final long FIRST_KEY = 5_000L;
	private static final long SECOND_KEY = 6_000L;

	private static final class CountingMemory implements KernelRuntime.MemoryAccount {
		private long reserved;

		@Override
		public boolean tryReserve(long bytes) {
			reserved += bytes;
			return true;
		}

		@Override
		public void release(long bytes) {
			reserved -= bytes;
		}
	}

	/**
	 * The open that closes a poor window both starts the bypass and arms a recording of its own key. When that arm is
	 * cut short, the rows of the keys opened during the bypass must not be published under the cut-short key.
	 */
	@Test
	void recordingCutShortAtWindowCloseDoesNotCollectBypassedKeys() {
		KernelOptionalReplay replay = boundedSite(new CountingMemory());
		long[] row = new long[2];
		armRecordingOnWindowClosingOpen(replay, row);
		// the arm of FIRST_KEY emits one row and is then stopped early: neither complete() nor abandon() is called
		row[VALUE] = 11L;
		replay.record(row);

		// a different key runs to exhaustion while the site bypasses the cache
		row[KEY] = SECOND_KEY;
		assertNull(replay.open(row));
		assertTrue(replay.lastOpenBypassed(), "the open after a poor window must bypass the cache");
		row[VALUE] = 22L;
		replay.record(row);
		replay.complete();

		// exhaust the rest of the bypass
		for (long i = 1; i < KernelOptionalReplay.INITIAL_BACKOFF; i++) {
			row[KEY] = SECOND_KEY + i;
			assertNull(replay.open(row));
			assertTrue(replay.lastOpenBypassed());
			replay.complete();
		}

		row[KEY] = FIRST_KEY;
		KernelOptionalReplay.Rows rows = replay.open(row);
		assertFalse(replay.lastOpenBypassed(), "the bypass must be over");
		assertNull(rows, "FIRST_KEY never ran to exhaustion, so it must not replay rows recorded for another key");
	}

	/** The cut-short recording is discarded by the next open, bypassing or not, and gives its bytes back. */
	@Test
	void recordingCutShortAtWindowCloseIsReleasedByBypassingOpen() {
		CountingMemory memory = new CountingMemory();
		KernelOptionalReplay replay = boundedSite(memory);
		long[] row = new long[2];
		armRecordingOnWindowClosingOpen(replay, row);
		row[VALUE] = 11L;
		replay.record(row);
		assertTrue(memory.reserved > 0L, "the armed recording must be charged");

		row[KEY] = SECOND_KEY;
		assertNull(replay.open(row));
		assertTrue(replay.lastOpenBypassed());

		assertEquals(0L, memory.reserved, "a discarded recording must not stay charged during the bypass");
	}

	private static KernelOptionalReplay boundedSite(CountingMemory memory) {
		return new KernelOptionalReplay(new KernelOptionalReplay.Budget(memory), new int[] { KEY },
				new int[] { VALUE }, true);
	}

	/**
	 * Runs one window of unique keys, so the last lookup of the window (for FIRST_KEY) starts the bypass and, being a
	 * miss, arms a recording.
	 */
	private static void armRecordingOnWindowClosingOpen(KernelOptionalReplay replay, long[] row) {
		for (long key = 1; key < KernelOptionalReplay.WINDOW; key++) {
			row[KEY] = key;
			assertNull(replay.open(row));
			assertFalse(replay.lastOpenBypassed());
			replay.complete();
		}
		row[KEY] = FIRST_KEY;
		assertNull(replay.open(row));
		assertFalse(replay.lastOpenBypassed(), "the window-closing open itself is a regular lookup");
	}
}
